class Solution {
public:
    long long minimumOperations(vector<int>& nums, vector<int>& target) {
        int n = nums.size();
        vector<long long> diff(n);
        for (int i = 0; i < n; ++i) {
            diff[i] = 1LL * target[i] - nums[i];
        }
        long long ops = abs(diff[0]);
        for (int i = 1; i < n; ++i) {
            if ((diff[i] >= 0 && diff[i - 1] >= 0) || (diff[i] <= 0 && diff[i - 1] <= 0)) {
                if (abs(diff[i]) > abs(diff[i - 1])) {
                    ops += abs(diff[i]) - abs(diff[i - 1]);
                }
            } else {
                ops += abs(diff[i]);
            }
        }
        return ops;
    }
};

class Solution {
    public long minimumOperations(int[] nums, int[] target) {
        int n = nums.length;
        long[] diff = new long[n];
        for (int i = 0; i < n; ++i) {
            diff[i] = (long) target[i] - nums[i];
        }
        long ops = Math.abs(diff[0]);
        for (int i = 1; i < n; ++i) {
            if ((diff[i] >= 0 && diff[i - 1] >= 0) || (diff[i] <= 0 && diff[i - 1] <= 0)) {
                if (Math.abs(diff[i]) > Math.abs(diff[i - 1])) {
                    ops += Math.abs(diff[i]) - Math.abs(diff[i - 1]);
                }
            } else {
                ops += Math.abs(diff[i]);
            }
        }
        return ops;
    }
}

var minimumOperations = function(nums, target) {
    const n = nums.length;
    const diff = new Array(n);
    for (let i = 0; i < n; i++) {
        diff[i] = target[i] - nums[i];
    }
    let ops = Math.abs(diff[0]);
    for (let i = 1; i < n; i++) {
        if ((diff[i] >= 0 && diff[i - 1] >= 0) || (diff[i] <= 0 && diff[i - 1] <= 0)) {
            if (Math.abs(diff[i]) > Math.abs(diff[i - 1])) {
                ops += Math.abs(diff[i]) - Math.abs(diff[i - 1]);
            }
        } else {
            ops += Math.abs(diff[i]);
        }
    }
    return ops;
};
